117	// git runs git in dir with a hermetic configuration.
118	func gitIn(t *testing.T, dir string, args ...string) {
119		t.Helper()
120		full := append([]string{
121			"-c", "user.name=Test", "-c", "user.email=test@example.invalid",
122			"-c", "commit.gpgsign=false", "-c", "init.defaultBranch=main",
123		}, args...)
124		cmd := exec.Command("git", full...)
125		cmd.Dir = dir
126		cmd.Env = append(os.Environ(), "GIT_CONFIG_GLOBAL=/dev/null", "GIT_CONFIG_SYSTEM=/dev/null")
127		if out, err := cmd.CombinedOutput(); err != nil {
128			t.Fatalf("git %v: %v\n%s", args, err, out)
129		}
130	}
