132	func writeFile(t *testing.T, dir, rel, content string) {
133		t.Helper()
134		p := filepath.Join(dir, filepath.FromSlash(rel))
135		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
136			t.Fatal(err)
137		}
138		if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
139			t.Fatal(err)
140		}
