143	// newRepo creates a repo with one base commit on main.
144	func newRepo(t *testing.T) string {
145		t.Helper()
146		dir := t.TempDir()
147		gitIn(t, dir, "init", "-q")
148		writeFile(t, dir, "main.go", "package main\n")
149		writeFile(t, dir, "internal/a.go", "package internal\n")
150		gitIn(t, dir, "add", "-A")
151		gitIn(t, dir, "commit", "-q", "-m", "base")
152		return dir
153	}
