155	func TestDocsOnlyDiff(t *testing.T) {
156		script := docsOnlyScript(t)
157		if _, err := exec.LookPath("git"); err != nil {
158			t.Skip("git not in PATH")
159		}
160		// merged builds a PR-like merge commit: a branch with the given edit,
161		// merged into main with --no-ff (a second main commit makes it a true merge).
162		merged := func(t *testing.T, edit func(dir string)) string {
163			dir := newRepo(t)
164			gitIn(t, dir, "checkout", "-q", "-b", "feature")
165			edit(dir)
166			gitIn(t, dir, "add", "-A")
167			gitIn(t, dir, "commit", "-q", "-m", "feature")
168			gitIn(t, dir, "checkout", "-q", "main")
169			gitIn(t, dir, "merge", "-q", "--no-ff", "-m", "merge", "feature")
170			return dir
171		}
172		tests := []struct {
173			name string
174			repo func(t *testing.T) string
175			want string
176		}{
177			{"docs-only branch", func(t *testing.T) string {
178				return merged(t, func(d string) {
179					writeFile(t, d, "docs/new.md", "x\n")
180					writeFile(t, d, "docs/img.png", "x\n")
181				})
182			}, "true"},
183			{"mixed branch", func(t *testing.T) string {
184				return merged(t, func(d string) {
185					writeFile(t, d, "docs/new.md", "x\n")
186					writeFile(t, d, "main.go", "package main\n// changed\n")
187				})
188			}, "false"},
189			{"rename from code to docs", func(t *testing.T) string {
190				return merged(t, func(d string) {
191					// internal/a.go is committed on the base by newRepo; git mv
192					// does not create the destination directory.
193					if err := os.MkdirAll(filepath.Join(d, "docs"), 0o755); err != nil {
194						t.Fatal(err)
195					}
196					gitIn(t, d, "mv", "internal/a.go", "docs/a.go")
197				})
198			}, "false"},
199			{"HEAD without second parent", func(t *testing.T) string {
200				d := newRepo(t)
201				writeFile(t, d, "docs/new.md", "x\n")
202				gitIn(t, d, "add", "-A")
203				gitIn(t, d, "commit", "-q", "-m", "docs")
204				return d
205			}, "false"},
206			{"single commit repo", newRepo, "false"},
207			{"not a git directory", func(t *testing.T) string { return t.TempDir() }, "false"},
208		}
209		for _, tt := range tests {
210			t.Run(tt.name, func(t *testing.T) {
211				dir := tt.repo(t)
212				out, code := runDocsOnly(t, script, dir, "", "diff")
213				if code != 0 {
214					t.Fatalf("exit code = %d, want 0", code)
215				}
216				if out != tt.want+"\n" && out != tt.want {
217					t.Fatalf("stdout = %q, want %q", out, tt.want)
218				}
219			})
220		}
221	}
